create table enrollment_codes(id uuid primary key default gen_random_uuid(),course_id uuid references courses(id),code text unique not null,max_uses int default 1,used_count int default 0,expires_at timestamptz,created_by uuid references profiles(id),created_at timestamptz default now());
create table enrollments(id uuid primary key default gen_random_uuid(),student_id uuid references profiles(id),course_id uuid references courses(id),organization_id uuid references organizations(id),enrolled_via text check(enrolled_via in('code','csv_import','manual')),status text default 'active' check(status in('active','completed','dropped')),progress_percent int default 0 check(progress_percent between 0 and 100),enrolled_at timestamptz default now(),unique(student_id,course_id));
create table live_sessions(id uuid primary key default gen_random_uuid(),course_id uuid references courses(id),instructor_id uuid references profiles(id),title text not null,meeting_url text,scheduled_start timestamptz not null,scheduled_end timestamptz not null,status text default 'scheduled' check(status in('scheduled','live','completed','cancelled')),created_at timestamptz default now());
create table session_attendance(id uuid primary key default gen_random_uuid(),session_id uuid references live_sessions(id) on delete cascade,student_id uuid references profiles(id),joined_at timestamptz,left_at timestamptz);
create table assignments(id uuid primary key default gen_random_uuid(),course_id uuid references courses(id),title text not null,description text,due_date timestamptz,max_score int default 100,created_at timestamptz default now());
create table assignment_submissions(id uuid primary key default gen_random_uuid(),assignment_id uuid references assignments(id) on delete cascade,student_id uuid references profiles(id),file_url text,submitted_at timestamptz default now(),score int,feedback text,graded_by uuid references profiles(id),graded_at timestamptz,unique(assignment_id,student_id));
create table quizzes(id uuid primary key default gen_random_uuid(),course_id uuid references courses(id),title text not null,time_limit_minutes int);create table quiz_questions(id uuid primary key default gen_random_uuid(),quiz_id uuid references quizzes(id) on delete cascade,question text not null,options jsonb,correct_option text,points int default 1);create table quiz_attempts(id uuid primary key default gen_random_uuid(),quiz_id uuid references quizzes(id),student_id uuid references profiles(id),answers jsonb,score int,submitted_at timestamptz default now());
create table certificates(id uuid primary key default gen_random_uuid(),student_id uuid references profiles(id),course_id uuid references courses(id),certificate_url text,issued_at timestamptz default now(),unique(student_id,course_id));create table announcements(id uuid primary key default gen_random_uuid(),course_id uuid references courses(id),posted_by uuid references profiles(id),title text not null,body text,created_at timestamptz default now());
alter table enrollment_codes enable row level security;alter table enrollments enable row level security;alter table live_sessions enable row level security;alter table session_attendance enable row level security;alter table assignments enable row level security;alter table assignment_submissions enable row level security;alter table quizzes enable row level security;alter table quiz_questions enable row level security;alter table quiz_attempts enable row level security;alter table certificates enable row level security;alter table announcements enable row level security;
create policy codes_manage on enrollment_codes for all using(app_role() in('super_admin','admin_staff') or exists(select 1 from courses c where c.id=course_id and c.instructor_id=auth.uid())) with check(app_role() in('super_admin','admin_staff') or created_by=auth.uid());
create policy enroll_read on enrollments for select using(student_id=auth.uid() or app_role() in('super_admin','admin_staff') or (organization_id=app_org() and app_role() in('organization','org_staff')) or exists(select 1 from courses c where c.id=course_id and c.instructor_id=auth.uid()));create policy enroll_staff on enrollments for all using(app_role() in('super_admin','admin_staff') or (organization_id=app_org() and app_role()='org_staff')) with check(app_role() in('super_admin','admin_staff') or (organization_id=app_org() and app_role()='org_staff'));
create policy sessions_read on live_sessions for select using(app_role() in('super_admin','admin_staff') or instructor_id=auth.uid() or exists(select 1 from enrollments e where e.course_id=course_id and e.student_id=auth.uid()));create policy sessions_manage on live_sessions for all using(app_role() in('super_admin','admin_staff') or instructor_id=auth.uid()) with check(app_role() in('super_admin','admin_staff') or instructor_id=auth.uid());
create policy attendance_read on session_attendance for select using(student_id=auth.uid() or app_role() in('super_admin','admin_staff') or exists(select 1 from live_sessions s where s.id=session_id and s.instructor_id=auth.uid()));create policy attendance_self on session_attendance for insert with check(student_id=auth.uid());
create policy assignment_read on assignments for select using(app_role() in('super_admin','admin_staff') or exists(select 1 from courses c left join enrollments e on e.course_id=c.id where c.id=course_id and(c.instructor_id=auth.uid() or e.student_id=auth.uid())));create policy assignment_manage on assignments for all using(app_role() in('super_admin','admin_staff') or exists(select 1 from courses c where c.id=course_id and c.instructor_id=auth.uid()));
create policy submission_read on assignment_submissions for select using(student_id=auth.uid() or app_role() in('super_admin','admin_staff') or exists(select 1 from assignments a join courses c on c.id=a.course_id where a.id=assignment_id and c.instructor_id=auth.uid()));create policy submission_create on assignment_submissions for insert with check(student_id=auth.uid());create policy submission_grade on assignment_submissions for update using(app_role() in('super_admin','admin_staff') or exists(select 1 from assignments a join courses c on c.id=a.course_id where a.id=assignment_id and c.instructor_id=auth.uid()));
create policy quiz_read on quizzes for select using(app_role() in('super_admin','admin_staff') or exists(select 1 from courses c left join enrollments e on e.course_id=c.id where c.id=course_id and(c.instructor_id=auth.uid() or e.student_id=auth.uid())));create policy quiz_manage on quizzes for all using(app_role() in('super_admin','admin_staff') or exists(select 1 from courses c where c.id=course_id and c.instructor_id=auth.uid()));
create policy questions_read on quiz_questions for select using(exists(select 1 from quizzes q join courses c on c.id=q.course_id left join enrollments e on e.course_id=c.id where q.id=quiz_id and(c.instructor_id=auth.uid() or e.student_id=auth.uid() or app_role() in('super_admin','admin_staff'))));create policy questions_manage on quiz_questions for all using(app_role() in('super_admin','admin_staff') or exists(select 1 from quizzes q join courses c on c.id=q.course_id where q.id=quiz_id and c.instructor_id=auth.uid()));
create policy attempts_read on quiz_attempts for select using(student_id=auth.uid() or app_role() in('super_admin','admin_staff') or exists(select 1 from quizzes q join courses c on c.id=q.course_id where q.id=quiz_id and c.instructor_id=auth.uid()));create policy attempts_create on quiz_attempts for insert with check(student_id=auth.uid());
create policy cert_read on certificates for select using(student_id=auth.uid() or app_role() in('super_admin','admin_staff') or exists(select 1 from courses c where c.id=course_id and c.instructor_id=auth.uid()));create policy cert_admin on certificates for all using(app_role() in('super_admin','admin_staff')) with check(app_role() in('super_admin','admin_staff'));
create policy announcements_read on announcements for select using(app_role() in('super_admin','admin_staff') or posted_by=auth.uid() or exists(select 1 from enrollments e where e.course_id=course_id and e.student_id=auth.uid()));create policy announcements_manage on announcements for all using(app_role() in('super_admin','admin_staff') or exists(select 1 from courses c where c.id=course_id and c.instructor_id=auth.uid()));
create or replace function redeem_enrollment_code(p_code text) returns uuid language plpgsql security definer set search_path=public as $$declare c enrollment_codes;eid uuid;begin select * into c from enrollment_codes where code=p_code for update;if c.id is null or c.used_count>=c.max_uses or(c.expires_at is not null and c.expires_at<now())then raise exception 'Invalid or expired enrollment code';end if;if app_role()<>'student' then raise exception 'Only students may redeem codes';end if;insert into enrollments(student_id,course_id,organization_id,enrolled_via)values(auth.uid(),c.course_id,app_org(),'code') on conflict(student_id,course_id) do update set status='active' returning id into eid;update enrollment_codes set used_count=used_count+1 where id=c.id;return eid;end$$;grant execute on function redeem_enrollment_code(text) to authenticated;
